class LazyImage : public Image {              // hand-written virtual proxy
  std::string path_;
  std::unique_ptr<Image> real_;
public:
  explicit LazyImage(std::string p) : path_(std::move(p)) {}
  void draw() override {
    if (!real_) real_ = std::make_unique<RealImage>(path_);
    real_->draw();
  }
};

class LoggingProxy : public Image {           // classic GoF forwarding class
  Image& real_;
  std::size_t calls_ = 0;
public:
  explicit LoggingProxy(Image& real) : real_(real) {}
  void draw() override { ++calls_; log(calls_); real_.draw(); }
};

